import{_ as e,o as t,c as o,ai as c}from"./chunks/framework.DAbPic9L.js";const g=JSON.parse('{"title":"界面样式规则（CSS）面试题集","description":"","frontmatter":{},"headers":[],"relativePath":"interviews/css.md","filePath":"interviews/css.md","lastUpdated":1783097192000}'),r={name:"interviews/css.md"};function a(s,d,i,l,n,p){return t(),o("div",null,[...d[0]||(d[0]=[c(`<h1 id="界面样式规则-css-面试题集" tabindex="-1">界面样式规则（CSS）面试题集 <a class="header-anchor" href="#界面样式规则-css-面试题集" aria-label="Permalink to &quot;界面样式规则（CSS）面试题集&quot;">​</a></h1><p>文/晨风不可依米</p><br><h2 id="如何理解-css-元素" tabindex="-1">如何理解 CSS 元素 <a class="header-anchor" href="#如何理解-css-元素" aria-label="Permalink to &quot;如何理解 CSS 元素&quot;">​</a></h2><p>描述对应<code>HTML</code>标签的样式锚点。</p><p>在<code>CSS</code>中，我们称<code>HTML</code>标签为元素；在<code>HTML</code>中，我们称<code>HTML</code>标签为节点。</p><p>因此，<code>HTML</code>标签在不同场合有不同叫法；无论是<code>标签</code>、<code>节点</code>、<code>元素</code>，本质上描述的是同一个话题内容。</p><h2 id="如何理解-css-盒模型" tabindex="-1">如何理解 CSS 盒模型 <a class="header-anchor" href="#如何理解-css-盒模型" aria-label="Permalink to &quot;如何理解 CSS 盒模型&quot;">​</a></h2><p>描述样式锚点所对应元素如何占据空间、如何计算尺寸；可通过样式规则<code>box-sizing</code>设置决定选用哪种盒模型。</p><p><code>CSS</code>盒模型，主要由<code>内容区域</code>、<code>内边距</code>、<code>边框</code>、<code>外边距</code>组成。</p><p><strong>常用盒模型</strong></p><ul><li><code>border-box</code>：内容区域宽度包含内边距、边框、外边距；俗称<code>IE 盒模型</code>。</li><li><code>content-box</code>：内容区域宽度不包含内边距、边框、外边距；俗称<code>W3C 盒模型</code>。</li></ul><p>个人推荐使用<code>border-box</code>盒模型，因为它更符合常理，更符合<code>HTML</code>元素的本质。</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 全局设置 */</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">*</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">::before</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">*</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">::after</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  box-sizing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">border-box</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="如何理解-css-属性值的计算过程" tabindex="-1">如何理解 CSS 属性值的计算过程 <a class="header-anchor" href="#如何理解-css-属性值的计算过程" aria-label="Permalink to &quot;如何理解 CSS 属性值的计算过程&quot;">​</a></h2><p><strong>样式规则计算过程</strong></p><ol><li>确定声明值：预设值、默认值以及自定义明确值。</li><li>样式层叠规则：根据样式规则的重要性（样式表来源）、优先级（选择器权重）以及源次序（书写顺序）决定最终样式规则。</li><li>样式继承规则：样式没有值，且样式属性有继承能力，可从上层元素继承。</li><li>沿用默认值：样式没有值，且无法继承其它样式规则；沿用浏览器默认值。</li></ol><p><code>CSS</code>属性值的计算过程，会优先将预设值转换为明确值，并通过有值不冲突确定部份最终样式规则，将有值冲突（多次赋值）的样式规则按照样式重要性（样式表来源）、优先级（选择器权重）以及源次序（书写顺序）计算最终样式规则。</p><p><strong>样式层叠规则维度</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>规则</th><th>说明</th></tr></thead><tbody><tr><td>重要性（样式表来源）</td><td>来源：默认样式表、用户样式表。 <br> 应用优先级：用户样式表 &gt; 默认样式表。</td><td>根据样式重要性程度决定优先应用。</td></tr><tr><td>优先级（选择器权重）</td><td>选择器：唯一选择器、类选择器、伪类选择器、元素选择器、伪元素选择器、通配符选择器等。 <br> 应用优先级：<code>!impotant</code> &gt; 唯一选择器 &gt; 类、属性、伪类等选择器 &gt; 元素、伪元素等选择器 &gt; 通配符选择器。</td><td>根据权重表示法（<code>0-0-0-0</code>）计算权重。</td></tr><tr><td>源次序（书写顺序）</td><td>应用优先级：后样式规则 &gt; 前样式规则</td><td>根据样式书写顺序决定最终应用。</td></tr></tbody></table><p><strong>样式继承规则条件</strong></p><ol><li>样式规则没有值；有值则用明确值。</li><li>样式规则属性有继承能力；无继承能力沿用默认值（用户自定义、浏览器默认）。</li></ol><p><strong>特别注意事项</strong></p><ul><li>开发者所设置的样式规则，只会影响样式规则计算过程的第<code>1</code>、<code>2</code>步；第<code>3</code>、<code>4</code>步由浏览器计算决定。</li><li>理解样式规则值（并非样式规则计算过程第<code>3</code>步） <ul><li><code>revert</code>：恢复为默认样式规则值。</li><li><code>initial</code>：浏览器默认样式规则值。</li><li><code>inherit</code>：拷贝上级元素样式规则值并应用。</li><li><code>unset</code>：重置样式规则，让浏览器重新计算样式规则值。</li></ul></li></ul><h2 id="如何理解-css-弹性布局-flex" tabindex="-1">如何理解 CSS 弹性布局（<code>Flex</code>） <a class="header-anchor" href="#如何理解-css-弹性布局-flex" aria-label="Permalink to &quot;如何理解 CSS 弹性布局（\`Flex\`）&quot;">​</a></h2><p>通过<code>display: flex</code>定义为弹性容器，弹性容器内的子元素可以称为弹性子项。</p><p>弹性容器不影响容器外或弹性子项内的正常渲染，只影响弹性子项在弹性容器内的对齐方式。</p><p><strong>核心属性</strong></p><table tabindex="0"><thead><tr><th>核心属性</th><th>属性描述</th><th>属性取值</th></tr></thead><tbody><tr><td><code>display</code></td><td>定义元素为弹性容器</td><td><code>flex</code>、<code>inline-flex</code></td></tr><tr><td><code>flex-direction</code></td><td>定义主轴方向</td><td><code>row</code>、<code>column</code> <br> <code>row-reverse</code>、<code>column-reverse</code></td></tr><tr><td><code>justify-content</code></td><td>定义主轴对齐方式</td><td><code>flex-start</code>、<code>flex-end</code>、<code>center</code> <br> <code>space-between</code>、<code>space-around</code></td></tr><tr><td><code>align-items</code></td><td>定义交叉轴对齐方式</td><td><code>flex-start</code>、<code>flex-end</code>、<code>center</code> <br> <code>baseline</code>、<code>stretch</code></td></tr><tr><td><code>flex-wrap</code></td><td>定义弹性子项是否换行</td><td><code>nowrap</code>、<code>wrap</code>、<code>wrap-reverse</code></td></tr><tr><td><code>align-content</code></td><td>定义多行交叉轴对齐方式</td><td><code>flex-start</code>、<code>flex-end</code>、<code>center</code> <br> <code>space-between</code>、<code>space-around</code></td></tr></tbody></table><p><span class="text-red"><strong>布局技巧</strong></span></p><ol><li>定义弹性容器，填充弹性子项。</li><li>定义主轴方向，确定主轴布局、再确定交叉轴布局。</li><li>弹性子项被挤压或隐藏时，考虑换行显示，再设置多行交叉的对齐方式。</li></ol><h2 id="如何理解-css-网格布局-grid" tabindex="-1">如何理解 CSS 网格布局（<code>Grid</code>） <a class="header-anchor" href="#如何理解-css-网格布局-grid" aria-label="Permalink to &quot;如何理解 CSS 网格布局（\`Grid\`）&quot;">​</a></h2><p>通过<code>display: grid</code>定义为网格容器，网格容器内的子元素可以称为网格子项。</p><p>注意事项：网格容器默认按列展示，网格子项默认转换为块级元素。</p><p>网格容器不影响容器外或网格子项内的正常渲染，只影响网格子项在网格容器内的放置位置。</p><p>网格布局，主要有<code>2</code>个操作流程；网格编排决定如何绘制网格线，子项放置决定网格内子项的位置。</p><p><strong>网格编排</strong></p><table tabindex="0"><thead><tr><th>核心属性</th><th>属性描述</th><th>属性取值</th></tr></thead><tbody><tr><td>显式网格</td><td></td><td></td></tr><tr><td><code>grid-template-columns</code></td><td>定义显式网格列的列数以及宽度</td><td><code>px</code>、<code>em</code>、<code>%</code>、<code>fr</code>、<code>auto</code> <br> <code>repeat(n, value)</code></td></tr><tr><td><code>grid-template-rows</code></td><td>定义显式网格行的的行数以及高度</td><td><code>px</code>、<code>em</code>、<code>%</code>、<code>fr</code>、<code>auto</code> <br> <code>repeat(n, value)</code></td></tr><tr><td><code>justify-content</code></td><td>定义网格线水平对齐</td><td><code>start</code>、<code>center</code>、<code>end</code>、<code>stretch</code>、<code>space-between</code>、<code>space-around</code>、<code>space-evenly</code></td></tr><tr><td><code>align-content</code></td><td>定义网格线纵向对齐</td><td><code>start</code>、<code>center</code>、<code>end</code>、<code>stretch</code>、<code>space-between</code>、<code>space-around</code>、<code>space-evenly</code></td></tr><tr><td><code>column-gap</code></td><td>定义网格列的间隔</td><td><code>px</code>、<code>em</code></td></tr><tr><td><code>row-gap</code></td><td>定义网格行的间隔</td><td><code>px</code>、<code>em</code></td></tr><tr><td></td><td></td><td></td></tr><tr><td>隐式网格</td><td></td><td></td></tr><tr><td><code>grid-auto-flow</code></td><td>定义隐式网格列的方向</td><td><code>row</code>、<code>column</code></td></tr><tr><td><code>grid-auto-rows</code></td><td>定义隐式网格列的列数以及宽度</td><td><code>px</code>、<code>em</code>、<code>%</code>、<code>fr</code>、<code>auto</code> <br> <code>repeat(n, value)</code></td></tr><tr><td><code>grid-auto-columns</code></td><td>定义隐式网格行的的行数以及高度</td><td><code>px</code>、<code>em</code>、<code>%</code>、<code>fr</code>、<code>auto</code> <br> <code>repeat(n, value)</code></td></tr><tr><td></td><td></td><td></td></tr><tr><td>速写属性</td><td></td><td></td></tr><tr><td><code>gap</code></td><td>速写网格行列的间隔（先行后列）</td><td></td></tr></tbody></table><p><span class="text-red">布局技巧</span></p><ul><li>样式函数：可通过<code>repeat</code>、<code>minmax</code>等函数设置重复次数、区间范围值。</li><li>网格布局：先定显式网格的行列宽高、再定网格线对齐方式、行列间隔，最后规范隐式网格的行列宽高。</li><li><code>auto-fill</code>表示尽可能多地填充内容；<code>auto-fit</code>表示以合适大小填充内容（会影响网格子项尺寸）。</li></ul><p><strong>子项放置</strong></p><table tabindex="0"><thead><tr><th>核心属性</th><th>属性描述</th><th>属性取值</th></tr></thead><tbody><tr><td><code>grid-row-start</code></td><td>定义网格子项所在行的起始位置。</td><td>数值；从<code>1</code>或<code>-1</code>开始。</td></tr><tr><td><code>grid-row-end</code></td><td>定义网格子项所在行的结束位置。</td><td>数值；从<code>1</code>或<code>-1</code>开始。</td></tr><tr><td><code>grid-column-start</code></td><td>定义网格子项所在列的起始位置。</td><td>数值；从<code>1</code>或<code>-1</code>开始。</td></tr><tr><td><code>grid-column-end</code></td><td>定义网格子项所在列的结束位置。</td><td>数值；从<code>1</code>或<code>-1</code>开始。</td></tr><tr><td></td><td></td><td></td></tr><tr><td>速写属性</td><td></td><td></td></tr><tr><td><code>grid-row</code></td><td>定义网格子项所在行的放置位置</td><td><code>start / end</code> 或 <code>start、end span 跨越数</code></td></tr><tr><td><code>grid-column</code></td><td>定义网格子项所在列的放置位置</td><td><code>start / end</code> 或 <code>start、end span 跨越数</code></td></tr></tbody></table><p><span class="text-red">布局技巧</span></p><ul><li>网格子项的位置是通过网格线的起始位置和结束位置所确定的；可通过<code>grid-row</code>、<code>grid-column</code>属性进行设置。</li></ul>`,44)])])}const b=e(r,[["render",a]]);export{g as __pageData,b as default};
